 * Error types the CLI distinguishes when deciding what to print and which
 * exit code to use.
 */

/** A validation failure that exits with a given status and prints one line. */
export class CliError extends Error {
  constructor(message, code) {
    super(message)
    this.code = code
  }
}

/** A dependency cycle found while scheduling; carries the reported path. */
export class CycleError extends Error {
  constructor(names) {
    super(`cycle: ${names.join(' -> ')}`)
    this.names = names
  }
}
"}

