{"file_path":"src/parse.js","content":"/**
 * Parses the build-graph text format into a graph of tasks and their
 * dependencies, per the rules in the task description.
 */
import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^\d+$/

/**
 * @param {string} input the raw standard input
 * @returns {{ tasks: Map<string, { name: string, cost: number }>, deps: Map<string, string[]> }}
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const deps = new Map()
  const depReferences = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`line ${lineNo}: expected task <name> <cost>`, 2)
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNo}: invalid task name ${name}`, 2)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`line ${lineNo}: cost must be a non-negative integer`, 2)
      }
      if (tasks.has(name)) {
        throw new CliError(`line ${lineNo}: task ${name} is declared twice`, 2)
      }
      tasks.set(name, { name, cost: Number(costStr) })
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`line ${lineNo}: expected dep <name> <dependency>...`, 2)
      }
      const subject = words[1]
      const dependencies = words.slice(2)
      depReferences.push(subject, ...dependencies)
      const list = deps.get(subject) ?? []
      for (const d of dependencies) {
        if (!list.includes(d)) list.push(d)
      }
      deps.set(subject, list)
    } else {
      throw new CliError(`line ${lineNo}: unknown directive ${directive}`, 2)
    }
  }

  for (const name of depReferences) {
    if (!tasks.has(name)) {
      throw new CliError(`unknown task ${name}`, 2)
    }
  }

  return { tasks, deps }
}
"}

