{"file_path":"src/graph.js","content":"/**
 * Graph algorithms shared by the `waves`, `explain` and `pack` commands:
 * cycle detection, the unlimited-worker schedule, chain priorities, and the
 * limited-worker pack simulation.
 */
import { CycleError } from './errors.js'

/**
 * Depth-first cycle check. Visits tasks and, within each task, its
 * dependencies, both in ascending name order, and reports the first cycle
 * found as a {@link CycleError}.
 */
export function detectCycle(tasks, deps) {
  const state = new Map()
  for (const name of tasks.keys()) state.set(name, 0)
  const stack = []

  function visit(node) {
    state.set(node, 1)
    stack.push(node)
    const depList = [...(deps.get(node) ?? [])].sort()
    for (const dep of depList) {
      const depState = state.get(dep)
      if (depState === 1) {
        const idx = stack.indexOf(dep)
        throw new CycleError([...stack.slice(idx), dep])
      }
      if (depState === 0) visit(dep)
    }
    state.set(node, 2)
    stack.pop()
  }

  for (const name of [...tasks.keys()].sort()) {
    if (state.get(name) === 0) visit(name)
  }
}

/**
 * The unlimited-worker schedule: each task's wave depth, start and finish.
 */
export function computeSchedule(tasks, deps) {
  const depth = new Map()
  const start = new Map()
  const finish = new Map()

  function getDepth(name) {
    if (depth.has(name)) return depth.get(name)
    const depList = deps.get(name) ?? []
    const value = depList.length === 0 ? 0 : 1 + Math.max(...depList.map(getDepth))
    depth.set(name, value)
    return value
  }

  function getFinish(name) {
    if (finish.has(name)) return finish.get(name)
    const depList = deps.get(name) ?? []
    const s = depList.length === 0 ? 0 : Math.max(...depList.map(getFinish))
    start.set(name, s)
    const f = s + tasks.get(name).cost
    finish.set(name, f)
    return f
  }

  for (const name of tasks.keys()) {
    getDepth(name)
    getFinish(name)
  }

  return { depth, start, finish }
}

/**
 * Each task's priority for `pack`: the cost of the longest chain of costs
 * from the task down through its dependents to one nothing depends on.
 */
export function computePriority(tasks, deps) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, depList] of deps) {
    for (const dep of depList) {
      if (dependents.has(dep)) dependents.get(dep).push(name)
    }
  }

  const priority = new Map()
  function get(name) {
    if (priority.has(name)) return priority.get(name)
    const dts = dependents.get(name) ?? []
    const value = tasks.get(name).cost + (dts.length === 0 ? 0 : Math.max(...dts.map(get)))
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) get(name)
  return priority
}

/**
 * Simulates the graph on `workerCount` workers, greedily starting the
 * highest-priority ready task on the lowest-index free worker at each
 * instant, and advancing time to the next worker-free instant otherwise.
 */
export function pack(tasks, deps, workerCount) {
  const priority = computePriority(tasks, deps)
  const remaining = new Set(tasks.keys())
  const finishOf = new Map()
  const workerLogs = Array.from({ length: workerCount }, () => [])
  const freeAt = Array(workerCount).fill(0)
  let currentTime = 0

  const isReady = (name) => {
    const depList = deps.get(name) ?? []
    return depList.every((d) => finishOf.has(d) && finishOf.get(d) <= currentTime)
  }

  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false
      const freeIdx = []
      for (let i = 0; i < workerCount; i++) if (freeAt[i] <= currentTime) freeIdx.push(i)
      if (freeIdx.length === 0) break

      const ready = [...remaining].filter(isReady)
      if (ready.length === 0) break

      ready.sort((a, b) => priority.get(b) - priority.get(a) || (a < b ? -1 : 1))
      const chosen = ready[0]
      const workerIndex = freeIdx[0]
      const start = currentTime
      const finish = start + tasks.get(chosen).cost

      workerLogs[workerIndex].push({ name: chosen, start, finish })
      freeAt[workerIndex] = finish
      finishOf.set(chosen, finish)
      remaining.delete(chosen)
      progressed = true
    }

    if (remaining.size === 0) break
    const future = freeAt.filter((t) => t > currentTime)
    if (future.length === 0) break
    currentTime = Math.min(...future)
  }

  const makespan = finishOf.size === 0 ? 0 : Math.max(...finishOf.values())
  return { workerLogs, makespan }
}
"}

