    let progressed = true
    while (progressed) {
      progressed = false
      const freeIdx = []
      for (let i = 0; i < workerCount; i++) if (freeAt[i] <= currentTime) freeIdx.push(i)
      if (freeIdx.length === 0) break

      const ready = [...remaining].filter(isReady)
      if (ready.length === 0) break

      ready.sort((a, b) => priority.get(b) - priority.get(a) || (a < b ? -1 : 1))
      const chosen = ready[0]
      const workerIndex = freeIdx[0]
      const start = currentTime
      const finish = start + tasks.get(chosen).cost

      workerLogs[workerIndex].push({ name: chosen, start, finish })
      freeAt[workerIndex] = finish
      finishOf.set(chosen, finish)
      remaining.delete(chosen)
      progressed = true
    }

    if (remaining.size === 0) break
    const future = freeAt.filter((t) => t > currentTime)
    if (future.length === 0) break
