/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'
import { CliError, CycleError } from './errors.js'
import { parseGraph } from './parse.js'
import { computePriority as _unused, computeSchedule, detectCycle, pack } from './graph.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9]\d*$/

function resolveMode(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError('workers must be a positive integer', 2)
    }
    return { mode: 'pack', workerCount: Number(argv[1]) }
  }
  throw new CliError(USAGE, 2)
}

function printWaves(tasks, depth, finish) {
  const maxDepth = tasks.size === 0 ? -1 : Math.max(...depth.values())
  const lines = []
  for (let k = 0; k <= maxDepth; k++) {
    const names = [...tasks.keys()].filter((n) => depth.get(n) === k).sort()
    lines.push(`wave ${k}: ${names.join(' ')}`)
  }
  const total = tasks.size === 0 ? 0 : Math.max(...finish.values())
  lines.push(`total ${total}`)
  process.stdout.write(lines.map((l) => `${l}\n`).join(''))
}

function printExplain(tasks, start, finish, depth) {
  const names = [...tasks.keys()].sort()
  const lines = names.map((n) => `${n} start=${start.get(n)} finish=${finish.get(n)} depth=${depth.get(n)}`)
  const total = tasks.size === 0 ? 0 : Math.max(...finish.values())
  lines.push(`total ${total}`)
  process.stdout.write(lines.map((l) => `${l}\n`).join(''))
}

function printPack(workerLogs, makespan) {
  const lines = workerLogs.map((log, i) => {
    const tail = log.map((t) => ` ${t.name}@${t.start}-${t.finish}`).join('')
    return `worker ${i}:${tail}`
  })
  lines.push(`makespan ${makespan}`)
  process.stdout.write(lines.map((l) => `${l}\n`).join(''))
}

function main() {
  const { mode, workerCount } = resolveMode(process.argv.slice(2))
  const input = readFileSync(0, 'utf8')
  const { tasks, deps } = parseGraph(input)
  detectCycle(tasks, deps)

  if (mode === 'waves') {
    const { depth, finish } = computeSchedule(tasks, deps)
    printWaves(tasks, depth, finish)
  } else if (mode === 'explain') {
    const { start, finish, depth } = computeSchedule(tasks, deps)
    printExplain(tasks, start, finish, depth)
  } else {
    const { workerLogs, makespan } = pack(tasks, deps, workerCount)
    printPack(workerLogs, makespan)
  }
}

try {
  main()
} catch (err) {
  if (err instanceof CycleError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(3)
  } else if (err instanceof CliError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(err.code)
  } else {
    throw err
  }
}
"}

